import sailpoint.connector.*;

Map map = JDBCConnector.buildMapFromResultSet(result, schema);
String LOGIN_AREAS = (String) map.get("LOGIN_AREAS");
if (LOGIN_AREAS != null) {
    String[] loginAreasArray = LOGIN_AREAS.split(",");
    map.put("LOGIN_AREAS", Arrays.asList(loginAreasArray));
}

return map;
